args.command:
cd /workspace && python -c "
import attrs, attr
from attr import fields, fields_dict
@attrs.define
class C:
    x: int
    y: str = 'a'
c = C(1)
print(fields(c) is fields(C))
print(fields(c))
try:
    fields(object())
except TypeError as e:
    print('TypeError:', e)
try:
    fields_dict(c)
except TypeError as e:
    print('fields_dict TypeError:', e)
a = fields(C)[0]
print('Attribute has __attrs_attrs__ on class:', hasattr(type(a), '__attrs_attrs__'))
try:
    fields(a)
except TypeError as e:
    print('fields(Attribute instance) TypeError:', e)
print(fields(int))
"
